{
  "morphology_wrong_forms": [
    {
      "wrong_form": "裁伴",
      "explanation": "Confuses the right-side component 判 with 伴, which is a common phonetic substitution error but changes the meaning completely."
    },
    {
      "wrong_form": "才判",
      "explanation": "Uses the wrong homophonous character 才 instead of 裁, failing to capture the 'cutting/judging' root meaning."
    },
    {
      "wrong_form": "栽判",
      "explanation": "Replaces the correct radical with the wood radical (栽), which relates to planting rather than legal judgment."
    }
  ],
  "l1_audio_confusables": [
    {
      "confusable_word": "才华",
      "explanation": "Sounds somewhat similar in initial consonants and tone contour to careless learners, though phonetically distinct to native speakers."
    },
    {
      "confusable_word": "彩排",
      "explanation": "Shares the 'cǎi' syllable sound with a similar nasal final, often leading to mishearings in fast-paced spoken contexts."
    },
    {
      "confusable_word": "参判",
      "explanation": "A near-homophone depending on regional accent variations of the first syllable (cái vs cān)."
    }
  ],
  "collocation_distractors": [
    {
      "distractor": "烹饪",
      "explanation": "Cooking verbs do not collocate with a legal or athletic referee term like 裁判."
    },
    {
      "distractor": " photosynthesis",
      "explanation": "Scientific processes cannot be the direct object or subject associated with a judge or referee."
    },
    {
      "distractor": "流利",
      "explanation": "Fluent is an adjective reserved for language skills, not judicial or referee rulings."
    }
  ],
  "collocation_wrong_collocate": {
    "planted_wrong_collocate": "炒裁判",
    "explanation": "The verb 炒 (to stir-fry or fire someone casually) does not collocate with 裁判; one typically uses 罢免 or infers official disciplinary actions."
  },
  "cloze_distractors": [
    {
      "option": "裁剪",
      "explanation": "Means 'to tailor' or 'to cut', which fits visually due to the shared first character 裁 but makes no sense in a judicial or sports context."
    },
    {
      "option": "批判",
      "explanation": "Means 'to criticize', which shares the second character 判 but alters the meaning to ideological criticism rather than formal judgment or refereeing."
    },
    {
      "option": "财产权",
      "explanation": "A legal term meaning 'property rights', tempting because of the legal theme, but it is a noun phrase rather than the verb/noun 'judge/referee'."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他在厨房里认真地裁判那条鱼该怎么切。",
      "reason": "Incorrect usage: 裁判 refers to legal judges or sports referees, not someone cutting fish in a kitchen."
    },
    {
      "sentence": "这本小说的裁判非常引人入胜。",
      "reason": "Incorrect usage: Novels have plots or writing styles (情节/文笔), not a referee or court judgment (裁判)."
    },
    {
      "sentence": "今天天气很好，我和朋友去公园裁判。",
      "reason": "Incorrect usage: 裁判 is a noun or verb of official judgment/refereeing, not an intransitive activity like strolling or playing."
    }
  ],
  "spot_incorrect": {
    "sentence": "这场足球比赛的裁判吹哨了，宣布红牌犯规。",
    "planted_error": "裁判吹哨了",
    "error_description": "While 裁判 can mean the referee, in this specific action context, it usually requires the classifier or noun phrase like 裁判员 to perform the physical action of blowing the whistle, or the verb is mismatched with the animate role.",
    "corrected_version": "这场足球比赛的主裁判吹了哨，宣布红牌犯规。"
  },
  "word_family_fake_forms": [
    "裁判性",
    "反裁判",
    "超裁判"
  ],
  "particle_candidates": [
    "が",
    "を",
    "に",
    "で"
  ]
}
